const { pool } = require(\"../db\");
const catalog = require(\"./catalog\");
const pricing = require(\"./pricing\");
const currency = require(\"./currency\");
const payments = require(\"./payments\");

async function placeOrder({ orderId, accountId, sku, quantity = 1, currency: cur = \"USD\" }) {
  if (catalog.listPrice(sku) === undefined) {
    throw new Error(\"unknown sku \" + sku);
  }
  const unitPrice = await pricing.priceFor(sku);
  const amountCents = currency.toUsdCents(unitPrice * quantity, cur);

  // Insert order with pending status in a transaction
  const client = await pool.connect();
  try {
    await client.query(\"BEGIN\");
    const result = await client.query(
      \"INSERT INTO orders (id, account_id, sku, quantity, amount_cents, currency, status) VALUES ("'$1, $2, $3, $4, $5, $6, '"'pending') ON CONFLICT (id) DO NOTHING RETURNING id\",
      [orderId, accountId, sku, quantity, amountCents, cur]
    );
    await client.query(\"COMMIT\");

    // If this is a retry and order already exists, we still need to process it
    const isNewOrder = result.rows.length > 0;
  } catch (err) {
    await client.query(\"ROLLBACK\");
    throw err;
  } finally {
    client.release();
  }

  // Process payment outside of transaction to avoid holding locks
  await payments.charge(orderId, amountCents);

  // Update order status to paid after successful charge
  const client2 = await pool.connect();
  try {
    await client2.query(\"UPDATE orders SET status = 'paid' WHERE id = "'$1", [orderId]);
  } finally {
    client2.release();
  }
}

module.exports = { placeOrder };
