const Module = require('module');
const originalRequire = Module.prototype.require;

Module.prototype.require = function(id) {
  const module = originalRequire.apply(this, arguments);

  // Intercept the Worker class from bullmq
  if (id === 'bullmq' && module.Worker) {
    const OriginalWorker = module.Worker;
    module.Worker = class PatchedWorker extends OriginalWorker {
      constructor(name, processor, opts = {}) {
        // Force concurrency to 1
        opts.concurrency = 1;
        super(name, processor, opts);
      }
    };
  }

  return module;
};

