const { pool } = require(\"../db\");
const catalog = require(\"./catalog\");
const pricing = require(\"./pricing\");
const currency = require(\"./currency\");
const payments = require(\"./payments\");

async function placeOrder({ orderId, accountId, sku, quantity = 1, currency: cur = \"USD\" }) {
  if (catalog.listPrice(sku) === undefined) {
    throw new Error(\"unknown sku \" + sku);
  }
  const unitPrice = await pricing.priceFor(sku);
  const amountCents = currency.toUsdCents(unitPrice * quantity, cur);

  const client = await pool.connect();
  try {
    await client.query(\"BEGIN\");

    // Try to insert the order. If it already exists, this will raise an error.
    // We'll catch it and check the existing status instead.
    let isNewOrder = true;
    let existingStatus = null;

    try {
      await client.query(
        \"INSERT INTO orders (id, account_id, sku, quantity, amount_cents, currency, status) VALUES ("'$1, $2, $3, $4, $5, $6, '"'pending')\",
        [orderId, accountId, sku, quantity, amountCents, cur]
      );
    } catch (insertErr) {
      // Order already exists. Check its status to avoid double-charging.
      isNewOrder = false;
      const result = await client.query(\"SELECT status FROM orders WHERE id = "'$1", [orderId]);
      if (result.rows.length > 0) {
        existingStatus = result.rows[0].status;
      }
    }

    // Only charge if:
    // 1. This is a new order, OR
    // 2. The order exists but is still pending (charge was never attempted or failed)
    if (isNewOrder || existingStatus === '"'pending') {
      await payments.charge(orderId, amountCents);
    } else if (existingStatus === 'paid') {
      // Order was already paid, just commit
      await client.query(\"COMMIT\");
      return;
    }

    // Update status to paid
    await client.query(\"UPDATE orders SET status = 'paid' WHERE id = "'$1", [orderId]);
    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

module.exports = { placeOrder };
