  connectionTimeoutMillis: config.dbTimeoutMs,
});

const MIGRATIONS_DIR = path.join(__dirname, \"..\", \"db\", \"migrations\");

async function migrate() {
  await pool.query(
    \"CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT now())\"
  );
  const { rows } = await pool.query(\"SELECT name FROM schema_migrations\");
  const applied = new Set(rows.map((r) => r.name));
  const files = fs.readdirSync(MIGRATIONS_DIR).filter((f) => f.endsWith(\".sql\")).sort();
  for (const file of files) {
    if (applied.has(file)) continue;
    const sql = fs.readFileSync(path.join(MIGRATIONS_DIR, file), \"utf8\");
    const client = await pool.connect();
    try {
      // Split statements to handle CREATE INDEX CONCURRENTLY separately
      const statements = sql.split(';').map(s => s.trim()).filter(s => s && "'!s.startsWith('"'--'));

      for (const statement of statements) {
        if (statement.toUpperCase().startsWith('CREATE INDEX')) {
          // CREATE INDEX cannot be in a transaction, execute directly
          await client.query(statement);
        } else {
          // Regular statements go in a transaction
          if (statements.indexOf(statement) === 0) {
            await client.query(\"BEGIN\");
            await client.query(\"SET LOCAL statement_timeout = 0\");
          }
          await client.query(statement);
        }
      }

      // Mark migration as applied
      await client.query(\"INSERT INTO schema_migrations (name) VALUES ("'$1) ON CONFLICT DO NOTHING", [file]);

      // Commit if in transaction
      try {
        await client.query("COMMIT");
      } catch (err) {
        // Already committed for index creation
      }
    } catch (err) {
      try {
        await client.query("ROLLBACK");
      } catch (rollbackErr) {
        // Already rolled back
      }
      throw err;
    } finally {
      client.release();
    }
  }
}

module.exports = { pool, migrate };
EOF
