const connection = new IORedis(\"redis://redis:6379\", { maxRetriesPerRequest: null });
const jobs = new Queue(\"jobs\", { connection });
const deadLetters = new Queue(\"jobs-dlq\", { connection });

async function fix() {
  console.log(\"Getting dead letter jobs...\");
  const deadLetterJobs = await deadLetters.getJobs([\"completed\", \"failed\", \"delayed\", \"active\", \"wait\"]);
  console.log("'`Found ${deadLetterJobs.length} dead letter jobs`);

  for (const dlJob of deadLetterJobs) {
    const jobId = dlJob.id;
    console.log(`'"\\nProcessing DL job: "'${jobId}`);

    // Get the existing job from the main queue
    const existingJob = await jobs.getJob(jobId);
    if (existingJob) {
      console.log(`Found existing job in main queue with state: ${existingJob.getState()}`);
      // Remove the existing job
      await existingJob.remove();
      console.log(`Removed existing job: ${jobId}`);
    }

    // Get clean data from DLQ (without error field)
    const jobData = dlJob.data;
    delete jobData.error;

    // Re-add to main queue with fresh state
    try {
      const newJob = await jobs.add("order", jobData, {
        jobId: jobId,
        attempts: 3,
        backoff: { type: "fixed", delay: 200 }
      });
      console.log(`Re-added job ${jobId} to main queue with state: ${newJob.getState()}`);
    } catch (err) {
      console.error(`Failed to add job ${jobId}:`, err.message);
    }
  }

  console.log("'"\\nFinal state check:\");
  const metrics = {
