const { pool } = require(\"../db\");

async function deposit({ depositId, accountId, amount }) {
  const client = await pool.connect();
  try {
    await client.query(\"BEGIN\");

    // Use RETURNING to detect if this was an actual insert (new row) or conflict (existing row)
    // We use a helper column or logic to track if this is the first processing
    const result = await client.query(
      "'`INSERT INTO deposits (id, account_id, amount) 
       VALUES ($1, $2, $3) 
       ON CONFLICT (id) DO NOTHING
       RETURNING id`,
      [depositId, accountId, amount]
    );

    // Only update balance if this was a new insert (returned a row)
    if (result.rows.length > 0) {
      await client.query("UPDATE accounts SET balance = balance + $1 WHERE id = $2", [amount, accountId]);
    }

    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

module.exports = { deposit };
