+const IORedis = require("ioredis");
+
+async function main() {
+  const redis = new IORedis("redis://shop-redis-1:6379");
+  
+  // Get all job IDs from the failed set
+  const failed = await redis.zrange("bull:jobs-dlq:failed", 0, -1);
+  console.log(`Found ${failed.length} failed jobs in DLQ`);
+  
+  for (const jobId of failed) {
+    const jobData = await redis.hgetall(`bull:jobs-dlq:${jobId}`);
+    
+    if (jobData && jobData.data && jobData.name) {
+      const data = JSON.parse(jobData.data);
+      const name = jobData.name;
+      const opts = JSON.parse(jobData.opts);
+      
+      console.log(`Replaying: ${name} ${jobId}`);
+      
+      // Add to regular queue
+      const timestamp = Date.now();
+      await redis.zadd(`bull:jobs:wait`, timestamp, jobId);
+      await redis.hset(`bull:jobs:${jobId}`,
+        "name", name,
+        "data", JSON.stringify(data),
+        "opts", JSON.stringify({ ...opts, attempts: 3 }),
+        "timestamp", timestamp,
+        "attemptsMade", 0,
+        "delay", 0,
+        "priority", 0
+      );
+    }
+  }
+  
+  console.log("All jobs replayed");
+  redis.disconnect();
+}
+
+main().catch(err => {
+  console.error("Error:", err.message);
+  process.exit(1);
+});
